// TS 4.5+: the recursive branch IS a conditional type, so it is eliminated.
type GetChars<S extends string, Acc extends string = never> =
  S extends `${infer Char}${infer Rest}`
    ? GetChars<Rest, Char | Acc>      // tail position, accumulator carries the work
    : Acc;

